 }
}
Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).

{
 "research_concepts": [
  "offensive reorganization",
  "points per possession (PPP)",
  "player absence impact",
  "play-type distribution",
  "baseline for offensive comparison"
 ],
 "methodological_questions": [
  "quantifying offensive reorganization",
  "measuring change in offensive efficiency",
  "defining baseline (L) for comparison",
  "controlling for confounders in player absence studies",
  "appropriate unit of analysis for team performance changes"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF20",
   "status_as_recorded": "untestable",
   "finding": "Real player absences move the association structure (V1) and the LOO simulation predicts the magnitude (V2). V1 (structure moves under real absence) was confirmed (e.g., 16/23 above own-null p95, binomial p=2.67e-16). V2 (simulation predicts magnitude) failed (Spearman +0.288, p=0.077, CI [-0.244, +0.667]) due to LIM:small_sample (23 player-season absences). A later full-pool run reportedly reversed V2."
  },
  {
   "id": "FAM:SF-APPS-009",
   "status_as_recorded": "untestable",
   "finding": "V5 player routing picks players with higher observed PPP than V4 routing. 8 divergences, 0 scoreable, 8 unscored (player missing from Neo4j); V5 mostly routed to 'team' rather than a player. A_unanswerable and LIM:small_sample, RISK:DRIFT_NONSTATIONARITY, RISK:SAMPLE_SIZE_POWER were noted."
  },
  {
   "id": "FAM:SF31",
   "status_as_recorded": "artifact",
   "finding": "The n>=15 H2H gate suppresses real player-routing signal. Mean PPP delta lead-default +1.259 (n>=5) to +1.129 (n>=15); low-n leaders are role players with 2-3 PPP on 5-7 possessions. Apparent +1.13 PPP edge is small-sample inflation (e.g. n=6, PPP=3.00), leading to C_artifact. n>=15 routing-override gate judged to filter noise."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF20",
   "what_failed": "Predicting the magnitude of structural changes caused by player absences (V2).",
   "why": "LIM:small_sample (23 player-season absences); initial test failed to confirm the hypothesis."
  },
  {
   "id": "FAM:SF-APPS-009",
   "what_failed": "Comparing V4 and V5 player routing on observed PPP.",
   "why": "A_unanswerable; 0 of 8 divergences were scoreable due to players missing from Neo4j and V5 routing to 'team'. LIM:small_sample, RISK:DRIFT_NONSTATIONARITY, RISK:SAMPLE_SIZE_POWER were also cited."
  },
  {
   "id": "FAM:SF31",
   "what_failed": "Estimating routing or matchup signals from cells with few possessions (e.g., n<15).",
   "why": "C_artifact (apparent effect produced by small-sample inflation); low-n cells (e.g., 5-7 possessions) produced inflated PPP values for role players."
  }
 ],
 "evidence_establishes": [
  "Player absences lead to observable changes in offensive 'association structure' (FAM:SF20).",
  "Quantifying the *magnitude* of these structural changes is challenging and sensitive to sample size (FAM:SF20).",
  "PPP calculations from small samples (e.g., fewer than 15 possessions) are unreliable and prone to small-sample inflation, leading to artifactual results (FAM:SF31). A minimum of 15 possessions is a recommended threshold for reliable PPP estimates.",
  "There are practical difficulties in accurately routing play-by-play data to specific players and obtaining player-level PPP from the graph database, which can result in unscorable cases and small sample sizes (FAM:SF-APPS-009)."
 ],
 "evidence_does_not_establish": [
  "A specific, validated metric for 'offensive reorganization' beyond the general concept of 'association structure'.",
  "A direct causal or predictive link between a quantified offensive reorganization metric and a change in team PPP.",
  "The minimum sample size required for reliable measurement of offensive reorganization itself, as opposed to PPP estimates."
 ],
 "own_inferences": [
  "The research question implies that player absence is the primary driver of offensive reorganization, and the measure of 'reorganization' should capture changes in play-type distribution or player roles.",
  "The 'L' in 'relative to L' likely refers to a baseline offensive structure or efficiency before the reorganization event (e.g., before player absence).",
  "PPP changes must be carefully attributed to reorganization rather than other confounding factors such as opponent strength or natural variance."
 ],
 "uncertainties": [
  "The precise definition and quantification of 'offensive reorganization' for this specific study, given that existing work only broadly confirmed 'association structure' changes.",
  "How to define the 'baseline (L)' and the period over which 'change in points per possession' is measured (e.g., pre-absence vs. post-absence, or game-over-game).",
  "The availability and reliability of play-type and player role data from the graph database for all relevant player absence scenarios, given the issues noted in FAM:SF-APPS-009."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence strongly influenced the decision by highlighting significant methodological risks and past failures related to small sample sizes in measuring both offensive structure changes (FAM:SF20) and reliable PPP (FAM:SF31). It also brought to light data quality and routing issues (FAM:SF-APPS-009) that could impact the core measurements. This evidence shifts the decision from a straightforward 'proceed' to 'proceed_with_changes', emphasizing the need for robust sample size criteria and careful definition of metrics to mitigate identified risks."
 },
 "testability": {
  "p_testable": 0.6,
  "blocking_constraints": []
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF20"
  ],
  "summary": "Previous work (FAM:SF20) established that player absences do cause changes in offensive 'association structure' (a form of reorganization). However, quantifying the *magnitude* of these changes and their predictive power for outcomes like PPP has not been directly tested or confirmed, and initial attempts to predict magnitude were hampered by small sample sizes."
 },
 "risks": [
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "Quantifying 'offensive reorganization' (e.g., changes in play-type distribution) and measuring reliable PPP values for specific play types or players requires a sufficient number of possessions. As seen in FAM:SF20 and FAM:SF31, small sample sizes lead to untestable hypotheses or artifactual results. The unit of analysis ('spells' given as n=148) may still be insufficient for robust analysis when further segmented by team, player, or play type."
  },
  {
   "code": "CONFOUNDING",
   "text": "Changes in points per possession can be influenced by numerous factors beyond offensive reorganization, such as opponent strength, game context (e.g., score differential, quarter), remaining players' individual performance fluctuations, coaching adjustments unrelated to 'reorganization', and natural variance. Isolating the effect of 'reorganization' will require careful control for these confounders."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The metric for 'offensive reorganization' needs to be robust and reliably measurable. If it relies on player-specific play-type data, the routing issues and missing player data noted in FAM:SF-APPS-009 could compromise its reliability. Similarly, PPP itself is prone to small-sample inflation (FAM:SF31)."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "Significant offensive reorganization events might be rare, or the specific types of reorganization that drive PPP changes might occur infrequently. This could lead to sparse data for certain reorganization patterns, making it difficult to detect a statistically significant relationship."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Player roles and team offensive schemes can evolve over a season or across seasons, making the definition of 'baseline (L)' and 'reorganization' potentially non-stationary. The historical evidence (FAM:SF-APPS-009) also noted this risk for routing comparisons."
  }
 ],
 "predicted_outcome": {
  "supported": 0.2,
  "rejected": 0.2,
  "untestable": 0.3,
  "artifact": 0.1,
  "uncertain": 0.2
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of the magnitude of offensive reorganization (quantified as a change in play-type distribution, weighted by player usage) on the change in team points per possession (PPP) following a significant player absence.",
  "unit": "Player-absence spell (defined as a sequence of games where a key offensive player is absent, with at least 5 games preceding and 5 games following the absence). Each spell will be associated with a team and a specific player absence. Data units are 'spells' (n=148) which will be further filtered.",
  "sample": "NBA regular season games from 2022-23 to 2025-26. Only player-absence spells where the absent player is a 'key offensive player' (e.g., top 3 in usage rate or minutes played for their team). Each spell must have at least 15 possessions per game in both the 'baseline' and 'post-absence' periods for all relevant play types and players contributing to the reorganization metric, to mitigate small-sample PPP issues (FAM:SF31). Spells with fewer than 15 games in either baseline or post-absence will be excluded. The total number of unique player-absence spells will be the primary sample unit.",
  "power": "A minimum effect size for PPP change of 0.05 (e.g., 1.15 to 1.20 PPP) for a 1-standard deviation change in reorganization metric. The power analysis will be conducted after defining the reorganization metric and establishing its variance, targeting 80% power at alpha=0.05. Given the historical `LIM:small_sample` for magnitude prediction (FAM:SF20), the sample size of 148 spells will be rigorously evaluated for power after filtering.",
  "controls": "Control for opponent strength (e.g., opponent defensive rating, opponent net rating), game context (e.g., home/away, back-to-back), and overall team quality (e.g., team net rating excluding the absent player's impact if possible). Baseline team PPP and offensive structure will be used as covariates. A difference-in-differences approach will be considered to control for time-invariant team characteristics.",
  "falsification": "A falsification test will involve analyzing 'pseudo-absence' periods where no key player was actually absent but a similar 'reorganization' is measured. If the model predicts PPP changes during these pseudo-absences, it suggests confounding or measurement issues. Additionally, if the relationship between reorganization and PPP change is strong for very small PPP samples (n<15), it would suggest an artifact (FAM:SF31).",
  "multiplicity": "Only one primary hypothesis test will be conducted: the prediction of change in PPP by offensive reorganization. No adjustments for multiple testing are anticipated for the primary analysis. If exploratory analyses are performed, they will be clearly marked as such.",
  "decision_rule": "The research question will be considered 'supported' if the coefficient for offensive reorganization (relative to L) predicting the change in points per possession is statistically significant (p < 0.05) and in the hypothesized direction, with a meaningful effect size. If the p-value is > 0.05 but the confidence interval includes a meaningful effect size, the outcome will be 'uncertain'. If the confidence interval excludes meaningful effects, it will be 'rejected'. If methodological issues prevent robust measurement or analysis (e.g., insufficient sample size after filtering, unreliable metrics), it will be 'untestable'.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25, and 2025-26 (partial) regular season and playoffs. Play-by-play data, substitution rotations, starters, defensive matchups, box-score summaries, and derived play-type possession records from the graph database."
 }
}

